<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import axios from 'axios'
import {api} from './session'
import {useTenantChanges} from './live-updates'
const props=defineProps<{tenantId:string;role:string;timezone:string}>()
interface Total {currency:string;order_count:number;gross_minor:string;captured_minor:string;refunded_minor:string;net_activity_minor:string}
interface Day {day:string;currency:string;gross_minor:string;refunded_minor:string;order_count:number}
interface Sales {snapshot_at:string;totals:Total[];daily:Day[];tenders:{currency:string;method:string;captured_minor:string;refunded_minor:string;net_minor:string}[]}
interface Reconciliation {checked_orders:number;discrepancy_count:number;balances:{currency:string;expected_minor:string;captured_minor:string;paid_refund_minor:string;pending_refund_minor:string}[];exceptions:{order_id:string;receipt_number:string;currency:string;expected_minor:string;captured_minor:string;paid_refund_minor:string;requested_refund_minor:string}[];pending_payments:{id:string;total_minor:string;card_minor:string;currency:string;unknown_provider:boolean}[];pending_refunds:{id:string;state:string;amount_minor:string;currency:string}[]}
interface Low {product_id:string;warehouse_id:string;product_name:string;warehouse_name:string;sku:string;unit:string;on_hand:string;reserved:string;available:string;reorder_point:string}
interface Audit {id:string;created_at:string;actor_id:string|null;actor_type:string;action:string;entity_type:string;entity_id:string;request_id:string|null;details:Record<string,unknown>|string}
const financial=computed(()=>props.role==='admin')
const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:props.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now)
const part=(type:string)=>parts.find(p=>p.type===type)!.value
const today=`${part('year')}-${part('month')}-${part('day')}`;const prior=new Date(`${today}T12:00:00Z`);prior.setUTCDate(prior.getUTCDate()-29)
const from=ref(prior.toISOString().slice(0,10)),to=ref(today),warehouse=ref(''),warehouses=ref<{id:string;name:string}[]>([])
const summary=ref<Sales>(),reconciliation=ref<Reconciliation>(),lows=ref<Low[]>([]),lowPage=ref(1),lowLast=ref(1),lowTotal=ref(0)
const audits=ref<Audit[]>([]),auditPage=ref(1),auditLast=ref(1),auditTotal=ref(0),action=ref(''),requestId=ref('')
const currency=ref(''),busy=ref(false),error=ref(''),auditOpen=ref(false)
const base=`/api/v1/tenants/${props.tenantId}/reports`
function money(raw:string,code:string){const n=BigInt(raw);const a=n<0n?-n:n;return `${code} ${n<0n?'-':''}${new Intl.NumberFormat().format(a/100n)}.${String(a%100n).padStart(2,'0')}`}
const daily=computed(()=>summary.value?.daily.filter(d=>d.currency===currency.value)??[])
function width(value:string){const max=daily.value.reduce((m,d)=>BigInt(d.gross_minor)>m?BigInt(d.gross_minor):m,0n);return max?`${Number(BigInt(value)*10000n/max)/100}%`:'0%'}
async function run(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=axios.isAxiosError(e)?Object.values(e.response?.data?.errors??{}).flat().join(' ')||e.response?.data?.message||'Reports unavailable. Reconnect and retry.':'Unable to load report.'}finally{busy.value=false}}
function period(){return {from:from.value,to:to.value,warehouse_id:warehouse.value||undefined}}
async function low(){const {data}=await api.get(`${base}/low-stock`,{params:{warehouse_id:warehouse.value||undefined,page:lowPage.value}});lows.value=data.data;lowTotal.value=data.total;lowLast.value=data.last_page}
async function audit(){const {data}=await api.get(`${base}/audit`,{params:{from:from.value,to:to.value,page:auditPage.value,action:action.value||undefined,request_id:requestId.value||undefined}});audits.value=data.data;auditTotal.value=data.total;auditLast.value=data.last_page}
async function load(){
 const tasks:Promise<unknown>[]=[low()]
 if(financial.value)tasks.push((async()=>{const [sales,rec]=await Promise.all([api.get(`${base}/sales`,{params:period()}),api.get(`${base}/reconciliation`,{params:period()})]);summary.value=sales.data;reconciliation.value=rec.data;if(!summary.value?.totals.some(t=>t.currency===currency.value))currency.value=summary.value?.totals[0]?.currency??''})())
 if(auditOpen.value&&financial.value)tasks.push(audit())
 await Promise.all(tasks)
}
async function locations(){let page=1,last=1;warehouses.value=[];do{const {data}=await api.get(`/api/v1/tenants/${props.tenantId}/warehouses`,{params:{page}});warehouses.value.push(...data.data);last=data.last_page;page++}while(page<=last)}
function details(a:Audit){return typeof a.details==='string'?JSON.parse(a.details):a.details}
onMounted(()=>run(async()=>{await locations();await load()}))
useTenantChanges(props.tenantId,['catalog','inventory','sales'],load)
</script>
<template>
<section class="bg-white border rounded-xl p-6 space-y-6" aria-label="Business reports">
 <h2 class="text-xl font-semibold">Reports &amp; audit</h2><p class="text-sm text-stone-600">Business timezone: {{timezone}}. Dates include both endpoints. Monetary totals are separated by currency.</p>
 <p v-if="error" role="alert" class="bg-red-50 p-3 text-red-800">{{error}}</p>
 <form @submit.prevent="lowPage=1;auditPage=1;run(load)" class="flex flex-wrap gap-3 items-end"><label v-if="financial">From<input v-model="from" type="date" required class="block border rounded p-2" /></label><label v-if="financial">Through<input v-model="to" type="date" required class="block border rounded p-2" /></label><label>Warehouse<select v-model="warehouse" class="block border rounded p-2"><option value="">All locations</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select></label><button :disabled="busy" class="bg-teal-800 text-white rounded px-4 py-2">Refresh reports</button></form>
 <template v-if="summary&&financial">
 <h3 class="font-semibold">Sales and settled money</h3><p class="text-sm text-stone-600">Gross sales use receipt completion dates. Refunds use the dates money was returned, including refunds of older receipts. Net activity is gross less those paid refunds.</p>
 <div v-for="total in summary.totals" :key="total.currency" class="grid sm:grid-cols-4 gap-3 border rounded p-4"><div><span class="text-stone-500 block">Receipts · {{total.currency}}</span><strong>{{total.order_count}}</strong></div><div><span class="text-stone-500 block">Gross sales</span><strong>{{money(total.gross_minor,total.currency)}}</strong></div><div><span class="text-stone-500 block">Paid refunds</span><strong>{{money(total.refunded_minor,total.currency)}}</strong></div><div><span class="text-stone-500 block">Net activity</span><strong>{{money(total.net_activity_minor,total.currency)}}</strong></div></div>
 <div><label>Daily sales currency <select v-model="currency" class="border rounded p-2"><option v-for="t in summary.totals" :key="t.currency">{{t.currency}}</option></select></label><div class="max-h-64 overflow-auto mt-4 space-y-2"><div v-for="day in daily" :key="day.day" class="grid grid-cols-[7rem_1fr_9rem] gap-3 items-center text-sm"><span>{{day.day}}</span><div class="bg-stone-100 rounded h-3"><div class="h-3 rounded bg-teal-700" :style="{width:width(day.gross_minor)}" /></div><span class="text-right">{{money(day.gross_minor,day.currency)}}</span></div></div></div>
 <div class="overflow-auto"><table class="w-full text-sm text-left"><caption class="text-left font-semibold pb-3">Payment ledger in the selected period</caption><thead><tr><th>Tender</th><th>Captured</th><th>Refunded</th><th>Net</th></tr></thead><tbody><tr v-for="t in summary.tenders" :key="`${t.currency}:${t.method}`" class="border-b"><td class="py-3">{{t.method}}</td><td>{{money(t.captured_minor,t.currency)}}</td><td>{{money(t.refunded_minor,t.currency)}}</td><td>{{money(t.net_minor,t.currency)}}</td></tr></tbody></table></div>
 </template>
 <div v-if="reconciliation&&financial" class="space-y-3 border-t pt-4"><h3 class="font-semibold">Payment reconciliation</h3><p>{{reconciliation.checked_orders}} receipts checked · {{reconciliation.discrepancy_count}} ledger discrepancies</p><p class="text-sm text-stone-600">For receipts completed in this period, compare lifetime recorded payments and refunds. Pending queues below show current outstanding work across all dates, up to 25 entries each. This does not reconcile bank payouts.</p><p v-for="b in reconciliation.balances" :key="b.currency">{{b.currency}} · Captured {{money(b.captured_minor,b.currency)}} · Paid refunds {{money(b.paid_refund_minor,b.currency)}} · Refunds outstanding {{money(b.pending_refund_minor,b.currency)}}</p><ul><li v-for="issue in reconciliation.exceptions" :key="issue.order_id" class="text-red-800 break-all">{{issue.receipt_number}} · Expected {{money(issue.expected_minor,issue.currency)}} · Captured {{money(issue.captured_minor,issue.currency)}} · Paid refunds {{money(issue.paid_refund_minor,issue.currency)}}</li></ul><p>Pending card attempts: {{reconciliation.pending_payments.length}}{{reconciliation.pending_payments.length===25?' (first 25)':''}}</p><ul><li v-for="p in reconciliation.pending_payments" :key="p.id" class="text-sm break-all">{{p.id}} · {{money(p.card_minor,p.currency)}}{{p.unknown_provider?' · provider result unknown':''}}</li></ul><p>Unfinished refunds: {{reconciliation.pending_refunds.length}}{{reconciliation.pending_refunds.length===25?' (first 25)':''}}</p><ul><li v-for="r in reconciliation.pending_refunds" :key="r.id" class="text-sm break-all">{{r.id}} · {{r.state}} · {{money(r.amount_minor,r.currency)}}</li></ul></div>
 <div class="space-y-3 border-t pt-4"><h3 class="font-semibold">Low stock · {{lowTotal}} product/location pairs</h3><p class="text-sm text-stone-600">Current available stock at or below the product reorder point, including missing balances as zero. Archived locations and products are excluded.</p><div class="overflow-auto"><table class="w-full text-sm text-left"><thead><tr><th>Product / location</th><th>On hand</th><th>Reserved</th><th>Available</th><th>Reorder point</th></tr></thead><tbody><tr v-for="row in lows" :key="`${row.product_id}:${row.warehouse_id}`" class="border-b"><td class="py-3">{{row.product_name}} · {{row.warehouse_name}}<span class="block text-stone-500">{{row.sku}} · {{row.unit}}</span></td><td>{{row.on_hand}}</td><td>{{row.reserved}}</td><td>{{row.available}}</td><td>{{row.reorder_point}}</td></tr></tbody></table></div><p v-if="!lows.length">No low-stock items.</p><div class="flex justify-between"><button :disabled="busy||lowPage<=1" @click="lowPage--;run(low)">Previous stock page</button><span>{{lowPage}} / {{lowLast}}</span><button :disabled="busy||lowPage>=lowLast" @click="lowPage++;run(low)">Next stock page</button></div></div>
 <div v-if="financial" class="space-y-3 border-t pt-4"><button :disabled="busy" @click="auditOpen=!auditOpen;if(auditOpen)run(audit)" class="font-semibold underline">{{auditOpen?'Hide audit trail':'Open audit trail'}}</button><template v-if="auditOpen"><p class="text-sm text-stone-600">Audit dates use the period above across all warehouses. Actor IDs identify memberships; automated entries identify their source.</p><form @submit.prevent="auditPage=1;run(audit)" class="flex flex-wrap gap-3"><label>Action<input v-model="action" placeholder="e.g. inventory.adjusted" class="block border rounded p-2" /></label><label>Request reference<input v-model="requestId" class="block border rounded p-2" /></label><button :disabled="busy" class="underline">Filter audit</button></form><p>{{auditTotal}} matching entries</p><details v-for="entry in audits" :key="entry.id" class="border rounded p-3"><summary>{{new Date(entry.created_at).toLocaleString()}} · {{entry.action}} · {{entry.actor_type}}</summary><p class="text-xs break-all mt-2">Actor: {{entry.actor_id??entry.actor_type}} · {{entry.entity_type}}: {{entry.entity_id}}</p><p v-if="entry.request_id" class="text-xs break-all">Request: {{entry.request_id}}</p><pre class="text-xs overflow-auto mt-2">{{JSON.stringify(details(entry),null,2)}}</pre></details><div class="flex justify-between"><button :disabled="busy||auditPage<=1" @click="auditPage--;run(audit)">Previous audit page</button><span>{{auditPage}} / {{auditLast}}</span><button :disabled="busy||auditPage>=auditLast" @click="auditPage++;run(audit)">Next audit page</button></div></template></div>
</section>
</template>
